use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (res: Vec<i32>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut out: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            out@.len() == i as int,
            i <= a.len(),
            forall|k: int| 0 <= k < i as int ==> out@[k] == a@[k],
        decreases a.len() - i,
    {
        out.push(a[i]);
        i += 1;
    }

    let alen: usize = a.len();
    let mut j: usize = 0;
    while j < b.len()
        invariant
            alen == a.len(),
            out@.len() == alen as int + j as int,
            j <= b.len(),
            forall|k: int| 0 <= k < alen as int ==> out@[k] == a@[k],
            forall|k: int| 0 <= k < j as int ==> out@[alen as int + k] == b@[k],
        decreases b.len() - j,
    {
        out.push(b[j]);
        j += 1;
    }

    out
}

} // verus!

